  navButton('tasks','Tasks & reminders','M5 4h14v17H5zM8 8h8m-8 4h8m-8 4h5');navButton('contacts','Contacts','M16 20v-1.5a4 4 0 0 0-4-4H7a4 4 0 0 0-4 4V20m6.5-8a3.5 3.5 0 1 0 0-7 3.5 3.5 0 0 0 0 7Zm7-6a3.5 3.5 0 0 1 0 6.8m1.5 2.7a4 4 0 0 1 3 3.5V20');navButton('business','Quotes & payments','M4 5h16v15H4zM8 9h8m-8 4h4m2 5 2-2 2 2');
  function section(id,title,sub,action){const s=document.createElement('section');s.className='view';s.id=id;s.innerHTML=`<div class="heading-row"><div><div class="eyebrow">PERSONAL WORKSPACE</div><h1>${title}</h1><p>${sub}</p></div>${action?`<button class="primary" data-action="${action}">+ Add new</button>`:''}</div><div class="data-page">${id==='business'?'<div class="card section-card"><div class="small-head"><b>Quotation drafts</b><button class="primary" data-action="add-quote">+ New quotation</button></div><div class="data-list" id="quote-list"></div></div><div class="card section-card"><div class="small-head"><b>Pending payments</b><button class="primary" data-action="add-payment">+ Add payment</button></div><div class="data-list" id="payment-list"></div></div>':`<div class="card section-card"><div class="data-toolbar"><input type="search" placeholder="Search ${title.toLowerCase()}…" data-search="${id}"><button class="primary" data-action="${action}">+ ${action==='add-task'?'Add task':action==='add-contact'?'Add contact':'Add reminder'}</button></div><div class="data-list" id="${id}-list"></div></div>`}</div>`;$('.content').append(s);return s}
