  const settings=$('#settings');const privacy=document.createElement('div');privacy.className='card section-card';privacy.innerHTML='<div class="small-head"><b>App data & installation</b><span class="connection-badge" id="ai-status">Local mode</span></div><p style="color:#91aaa0;font-size:11px;line-height:1.6">Your meetings, contacts, reminders and memories stay in this browser profile. Export a backup before changing devices. Live AI can be enabled by the optional secure server setup in README.</p><div class="data-toolbar"><button class="primary" data-action="export">Export my data</button><label class="row-action" style="cursor:pointer">Import backup<input type="file" id="import-file" accept="application/json" hidden></label><button class="row-action danger" data-action="wipe">Delete all local data</button><button class="install-cta" id="install-app">Install app</button></div><div style="font-size:10px;color:#8ca99d">Voice activation is user initiated. Wake word is not enabled. Meeting recording is never started by voice command.</div>';
