  function renderTasks(filter=''){const list=$('#tasks-list');if(!list)return;const q=filter.toLowerCase();const tasks=db.tasks.filter(x=>`${x.title} ${x.notes||''}`.toLowerCase().includes(q)).sort((a,b)=>a.due.localeCompare(b.due));list.innerHTML=tasks.length?tasks.map(t=>`<div class="data-row" data-id="${esc(t.id)}"><div class="data-icon">${t.done?'✓':'◷'}</div><div><strong style="${t.done?'text-decoration:line-through;opacity:.65':''}">${esc(t.title)}</strong><small>${esc(t.notes||'Reminder')} · ${t.done?'Completed':fmtDate(t.due)}${!t.done&&t.due<today()?' · OVERDUE':''}</small></div><div class="row-actions"><button class="row-action" data-action="toggle-task">${t.done?'Reopen':'Complete'}</button><button class="row-action danger" data-action="delete-task">Delete</button></div></div>`).join(''):'<div class="empty-state"><b>No tasks here yet</b>Add a reminder or ask MeetingMind to remind you about something.</div>'}
