  function renderBusiness(){const q=$('#quote-list'),p=$('#payment-list');if(!q||!p)return;q.innerHTML=db.quotes.length?db.quotes.map(x=>`<div class="data-row" data-id="${esc(x.id)}"><div class="data-icon">＄</div><div><strong>${esc(x.customer)} · ${esc(x.title)}</strong><small>${esc(x.status)}${x.amount?' · '+esc(x.amount):''} · ${fmtDate(x.date)}${x.sentAt?' · Sent '+fmtDate(x.sentAt):''}${x.followUpDue?' · Follow-up '+fmtDate(x.followUpDue):''}${x.followUpDoneAt?' · Follow-up done':''}${x.notes?' · '+esc(x.notes):''}</small></div><div class="row-actions"><button class="row-action" data-action="quote-file">Download quotation</button>${x.status==='Draft'?'<button class="row-action" data-action="quote-sent">Record sent</button>':''}${x.status==='Sent'&&!x.followUpDoneAt?'<button class="row-action" data-action="quote-followup">Complete follow-up</button>':''}${x.status==='Sent'?'<button class="row-action" data-action="quote-outcome">Update outcome</button>':''}<button class="row-action danger" data-action="delete-quote">Delete</button></div></div>`).join(''):'<div class="empty-state"><b>No quotations</b>Create a draft; it will not be sent.</div>';p.innerHTML=db.payments.length?db.payments.map(x=>`<div class="data-row" data-id="${esc(x.id)}"><div class="data-icon">₹</div><div><strong>${esc(x.customer)} · ${esc(x.status)}</strong><small>${x.amount?'Amount '+esc(x.amount)+' · ':''}Due ${fmtDate(x.due)}${x.notes?' · '+esc(x.notes):''}</small></div><div class="row-actions"><button class="row-action" data-action="toggle-payment">${x.status==='Paid'?'Mark pending':'Mark paid'}</button><button class="row-action danger" data-action="delete-payment">Delete</button></div></div>`).join(''):'<div class="empty-state"><b>No payments tracked</b>Add a payment follow-up to keep it on your radar.</div>'}
  function meetingEnded(m){return new Date(`${m.date}T${m.time||'09:00'}`).getTime()+(Number(m.duration)||30)*60000<=Date.now()}
  function renderSchedule(){const list=$('.schedule-list');if(!list)return;const rows=db.meetings.filter(x=>x.date>=today()||(!x.completedAt&&meetingEnded(x))).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));list.innerHTML=rows.length?rows.map(m=>`<div class="schedule-row" data-id="${esc(m.id)}"><time>${fmtDate(m.date)}<br>${esc(m.time)}</time><span class="schedule-dot"></span><div><strong>${esc(m.title)}</strong><small>${esc(m.attendees||'Meeting')} · ${m.duration||30} min · ${esc(m.completedAt?'Completed':meetingEnded(m)?'Check in needed':m.notes||'')}</small></div>${m.completedAt?'<span class="row-action">Done</span>':meetingEnded(m)?'<button data-action="meeting-complete">Log outcome</button>':`<button data-action="meeting-brief">Brief</button><button data-action="meeting-record">Record</button>`}</div>`).join(''):'<div class="empty-state"><b>No meetings scheduled</b>Add a meeting to see it here. Ended meetings stay here until you log their outcome.</div>';renderMeetingHistory()}
  function renderMeetingHistory(){const list=$('#meeting-history-list');if(!list)return;const rows=[...db.meetings].sort((a,b)=>(b.date+b.time).localeCompare(a.date+a.time));list.innerHTML=rows.length?rows.map(m=>`<div class="memory-row" data-id="${esc(m.id)}"><div class="brief-icon">◷</div><div><strong>${esc(m.title)} · ${esc(m.customer||'')}</strong><p>${fmtDate(m.date)} · ${esc(m.attendees||'No attendees added')} · ${esc(m.outcomeNotes||m.outcome||m.notes||'No notes yet')}</p>${m.transcript?`<p>${esc(m.transcript.slice(0,360))}${m.transcript.length>360?'…':''}</p>`:''}</div><button class="row-action" data-action="meeting-record">${m.completedAt?'Record more':'Record'}</button>${!m.completedAt?'<button class="row-action" data-action="meeting-complete">Log outcome</button>':''}</div>`).join(''):'<div class="empty-state"><b>No meetings yet</b>Create a meeting or use the microphone to capture a discussion.</div>'}
