  function syncHome(){const count=db.meetings.filter(x=>x.date===today()&&!x.completedAt).length,open=db.tasks.filter(x=>!x.done).length;const briefing=$('.lower .small-card:nth-child(1) .briefing strong');if(briefing)briefing.textContent=`${count} meeting${count===1?'':'s'} · ${open} open follow-up${open===1?'':'s'}`;const briefingText=$('.lower .small-card:nth-child(1) .briefing p');if(briefingText)briefingText.textContent=count?'Your saved schedule is up to date.':'Add your first meeting to get started.';const stats=$$('.lower .small-card:nth-child(2) .stat');const counts=[db.quotes.filter(x=>!['Accepted','Declined','Won','Lost'].includes(x.status)).length,db.payments.filter(x=>x.status==='Pending').length,open],labels=['active','pending','open'];counts.forEach((n,i)=>{if(stats[i]){stats[i].querySelector('strong').textContent=String(n).padStart(2,'0');stats[i].querySelector('em').textContent=labels[i]}});const recent=$('.lower .small-card:nth-child(3)');if(recent){const m=db.memories.slice(-2).reverse();const target=recent.querySelectorAll('.memory-item');target.forEach((r,i)=>{if(m[i])r.querySelector('span').textContent=`${m[i].title} · ${m[i].body.slice(0,38)}`;else r.querySelector('span').textContent='No saved memories yet'})}const date=$('.topbar .date');if(date)date.textContent=new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'});const greet=$('#home .heading-row h1');if(greet){const h=new Date().getHours();greet.textContent=`Good ${h<12?'morning':h<18?'afternoon':'evening'}, Rushabh`}}
  const meetingsView=$('#meetings');if(meetingsView)meetingsView.innerHTML=`<div class="heading-row"><div><div class="eyebrow">YOUR CONVERSATIONS, CONNECTED</div><h1>Meetings</h1><p>Record discussions, review live transcripts, and capture decisions and next steps.</p></div><button class="primary" data-action="add-meeting">+ Add meeting</button></div><div class="card section-card"><div class="data-list" id="meeting-history-list"></div></div>`;
