  const form=replace('composer'), promptInput=$('#prompt'), chat=$('#chat');const addMem=replace('add-memory'),clearMem=replace('clear-memory'),remindBtn=replace('remind'),newMeeting=replace('new-meeting'),talk=replace('talk'),mic=replace('mic'),saveVoice=replace('save-voice'),deleteHistory=replace('delete-history');
  const dialog=$('#app-dialog'),fields=$('#dialog-fields');
