  function voiceGender(v){const s=`${v.name} ${v.voiceURI} ${v.gender||''}`.toLowerCase();if(v.gender==='female'||/female|woman|girl|aria|jenny|samantha|zira|eva|joanna|karen|susan|hazel|sonia|heera|veena|priya|google.*female|microsoft.*(zira|aria|jenny|sonia|heera|veena)/i.test(s))return'female';if(v.gender==='male'||/male|david|mark|guy|ryan|brian|daniel|thomas|alex|prabhat|rishi|google.*male|microsoft.*(david|mark|guy|ryan|prabhat)/i.test(s))return'male';return'unknown'}
  function resolveVoice(profile=db.settings.voice,lang=db.settings.language){if(!('speechSynthesis'in window))return null;if(db.settings.deviceVoiceURI){const pinned=deviceVoices.find(v=>v.voiceURI===db.settings.deviceVoiceURI);if(pinned)return pinned}const wanted=/female/i.test(profile)?'female':/male|deep professional/i.test(profile)?'male':'';let candidates=deviceVoices.filter(v=>!wanted||voiceGender(v)===wanted);if(!candidates.length)return null;const code=languageTag(lang).split('-')[0];candidates.sort((a,b)=>Number(b.lang.toLowerCase().startsWith(code))-Number(a.lang.toLowerCase().startsWith(code)));const sameGender=candidates;let slot=0;if(/friendly/i.test(profile))slot=1;if(/deep/i.test(profile))slot=2;return sameGender[Math.min(slot,sameGender.length-1)]}
  function refreshVoicePicker(){if(!('speechSynthesis'in window))return;deviceVoices=speechSynthesis.getVoices();let picker=$('#device-voice');if(!picker){const list=$('#voice-list');if(!list)return;const wrap=document.createElement('div');wrap.className='control device-voice-control';wrap.innerHTML='<label for="device-voice">Actual voice installed on this device</label><select id="device-voice" class="select-control"><option value="">Choose automatically from voice style</option></select><small class="voice-availability" id="voice-availability"></small>';list.insertAdjacentElement('afterend',wrap);picker=$('#device-voice');picker.addEventListener('change',()=>{db.settings.deviceVoiceURI=picker.value;save();updateVoiceStatus();notify(picker.value?'Device voice selected':'Automatic voice matching enabled')})}const previous=db.settings.deviceVoiceURI||'';picker.innerHTML='<option value="">Choose automatically from voice style</option>'+deviceVoices.map(v=>`<option value="${esc(v.voiceURI)}">${esc(v.name)} · ${esc(v.lang)}</option>`).join('');picker.value=deviceVoices.some(v=>v.voiceURI===previous)?previous:'';if(previous&&!picker.value){db.settings.deviceVoiceURI='';save()}updateVoiceStatus()}
  function setActivity(state,label,hint){const card=$('.orb-card');if(card){card.classList.remove('activity-listening','activity-reading','activity-thinking','activity-speaking','activity-recording');if(state)card.classList.add(`activity-${state}`)}if($('#orb-label'))$('#orb-label').textContent=label;if($('#orb-hint'))$('#orb-hint').textContent=hint}
  function updateVoiceStatus(){const el=$('#voice-availability');if(!el)return;const profile=db.settings.voice||'Deep Professional',voice=resolveVoice(profile);el.textContent=voice?`${profile} uses ${voice.name} (${voice.lang}). You can choose another installed voice above.`:/female/i.test(profile)?'No voice identified as female is installed for this language on this device. Select another voice above or install a female system voice.':'No matching voice is installed. Choose an available voice above.';const foot=$('.voice-foot span');if(foot)foot.textContent=voice?`Voice · ${profile} · ${voice.name}`:`Voice · ${profile} · unavailable`}
  function speakWithSelectedVoice(text,preview=false){if(!('speechSynthesis'in window)){notify('Speech output is not supported in this browser.');return}const profile=preview?preview:db.settings.voice,voice=resolveVoice(profile);if(!voice){notify(`No installed device voice matches “${profile}”. Choose an actual voice in Voice Studio.`);return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text),pitch={'Professional Male':0.96,'Friendly Male':1.05,'Deep Professional':0.86,'Professional Female':1.02,'Friendly Female':1.12,'Calm Conversational':0.92,'Energetic Assistant':1.18,'Gujarati Voice':1.04}[profile]||1,pace={'Professional Male':0.98,'Friendly Male':1.03,'Deep Professional':0.94,'Professional Female':0.99,'Friendly Female':1.04,'Calm Conversational':0.91,'Energetic Assistant':1.12}[profile]||1;u.voice=voice;u.lang=voice.lang;u.rate=Math.min(1.25,Math.max(.75,Number(db.settings.speed||$('#speed')?.value||1)*pace));u.pitch=pitch;u.volume=Math.min(1,Math.max(0,Number(db.settings.volume??80)/100));u.onstart=()=>setActivity('speaking',preview?'Playing voice preview':'Speaking','Tap Stop speaking to interrupt');u.onend=()=>setActivity('','Ready','Tap to start a voice conversation');speechSynthesis.speak(u)}
